INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103435, 'spa', 'estar angustiado', 'El sentido estativo Qal de angustia emocional o psicológica, que describe turbación interior y aflicción. El español ''angustia'' y el alemán ''Angst'' conservan el vínculo etimológico entre estrechez y ansiedad que esta raíz hebrea encarna. Prominente en momentos narrativos de crisis: Gn 32:7 (Jacob antes de encontrarse con Esaú), Jue 2:15 y 10:9 (Israel bajo presión enemiga), 1 S 30:6 (David en Siclag), 2 S 13:2 (Amnón por Tamar).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103436, 'spa', 'ser estrecho o constreñido', 'El sentido Qal de estrechez espacial o física: ser demasiado constreñido, demasiado pequeño, o estar impedido en el movimiento. Job 18:7 lo usa para pasos que ''se acortan'', Proverbios 4:12 para pasos que ''no serán estorbados'', e Isaías 49:19 para una tierra demasiado estrecha para sus habitantes que regresan. El español ''estrecha'' y ''estrechan'' reflejan claramente esta dimensión espacial concreta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103440, 'spa', 'oprimir o causar angustia', 'El sentido causativo Hifil de infligir angustia u opresión sobre otros. Atestiguado únicamente en Nehemías 9:27, donde los enemigos ''angustiaron'' a Israel durante sus períodos de rebelión. El español ''angustiaron'' y el inglés ''oppressed'' captan la fuerza transitiva y causativa que distingue esta conjugación de los usos estativos del Qal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103445, 'spa', 'Alfarero, artesano', 'Alfarero, artesano: participio Qal usado como sustantivo: alfarero, artesano de arcilla, con 18 ocurrencias donde יוֹצֵר funciona como sustantivo ocupacional. Incluye alfareros literales en su oficio (1 Cr 4:23, ''los alfareros que habitaban entre plantas y cercas''), cerámica quebrada (Is 30:14, un vaso ''destruido como vasija de alfarero'') y la sostenida metáfora alfarero-arcilla de Is 29:16 (''¿Dirá el objeto formado al que lo formó...?'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103447, 'spa', 'Formar, crear, modelar', 'Formar, crear, modelar: Qal activo: formar, modelar, dar forma o crear, el sentido primario con 40 ocurrencias, dominado por Dios como sujeto. Dios forma al ser humano del polvo (Gn 2:7), forma a toda bestia del campo (Gn 2:19), forma el ojo (Sal 94:9), forma los montes (Am 4:13), forma la tierra para ser habitada (Is 45:18) y forma a Israel como su pueblo (Is 43:1, 7, 21; 44:2, 21, 24). El árabe jabala (''moldear, crear'') confirma el sentido artesanal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103463, 'spa', 'Planificar, idear, determinar', 'Planificar, idear, determinar: Qal con significado cognitivo-planificador: determinar, planificar o idear, con 2 ocurrencias en 2 R 19:25 y su paralelo Is 37:26, donde Dios declara ''¿No has oído que desde hace mucho lo formé? Desde tiempos antiguos lo planifiqué''. Aquí יָצַר se extiende del modelado físico al diseño mental, la metáfora del plano del artesano aplicada a la intención divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103473, 'spa', 'Forjada (participio pasivo)', 'Forjada (participio pasivo): una sola ocurrencia en Is 54:17 describiendo un arma ''forjada'' contra el pueblo de Dios. El participio pasivo יֻצַּר (''que es formada/forjada'') aplica la metáfora del modelado a instrumentos hostiles: ningún arma que sea forjada contra ti prosperará. El español forjada capta la extensión metalúrgica del acto de formar del alfarero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103475, 'spa', 'Fueron formados (Pual pasivo)', 'Fueron formados (Pual pasivo): una sola ocurrencia en Pual pasivo en Sal 139:16: ''Mi embrión vieron tus ojos; en tu libro estaban escritos, todos ellos, los días que fueron formados para mí''. El pasivo ''fueron formados'' describe la formación pre-creativa de los días de una persona por parte de Dios antes de que existieran. El español fueron formados trata esto como el pasivo del sentido primario de formar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103482, 'spa', 'Fue formado (Nifal pasivo)', 'Fue formado (Nifal pasivo): una sola ocurrencia en Nifal en Is 43:10: ''antes de mí no fue formado dios, ni lo será después de mí''. La voz pasiva (''fue formado/modelado'') aplica la metáfora artesanal a la inexistencia de otros dioses: ninguna deidad fue jamás modelada o traída a la existencia aparte de Yahvé. La polémica anti-idolátrica es potente: el mismo verbo usado para la creación de Dios niega la formación de cualquier otro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103490, 'spa', 'inclinación, disposición', 'La disposición o inclinación interior del corazón, la tendencia predeterminada del pensamiento y el deseo humano. Génesis 6:5 la empareja con ''todo designio de los pensamientos de su corazón'', y Génesis 8:21 repite la misma frase tras el Diluvio, anclando la palabra en la constitución moral de la humanidad. Deuteronomio 31:21 y los pasajes de Crónicas (1 Cr 28:9; 29:18) la extienden a planes y propósitos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103491, 'spa', 'constitución física', 'La constitución o condición física del ser humano, usada en Salmo 103:14 donde Dios ''conoce nuestra condición; se acuerda de que somos polvo''. La palabra tiende un puente entre la metáfora del alfarero y el tema de la mortalidad: los humanos fueron formados del barro y siguen siendo frágiles. El árabe jibilla (''constitución natural'') y el francés forme reflejan este sentido de debilidad creatural más que de tendencia moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103494, 'spa', 'cosa formada, producto', 'El producto concreto de la acción de formar: una vasija moldeada por un alfarero o un ídolo tallado por un artesano. Isaías 29:16 plantea la amarga ironía: ''¿Dirá la obra a su hacedor: No me hiciste?'' Habacuc 2:18 también lo aplica a un ídolo. El español ''obra'' y el coreano 만든 것 (''cosa hecha'') captan el resultado tangible y físico. Aquí יֵצֶר no es una tendencia interior sino un artefacto exterior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103496, 'spa', 'hacedor, formador', 'El participio activo Qal יוֹצֵר usado como sustantivo con el significado de ''hacedor, formador'': el agente y no el producto. En Habacuc 2:18 aparece junto al sentido nominal: el hacedor (יוֹצֵר) confía en lo que ha formado (יֵצֶר). El español ''hacedor'' y el árabe صانع (''artesano'') muestran con claridad la fuerza participial. Aunque morfológicamente emparentado con el sustantivo, este sentido señala al agente que da forma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103499, 'spa', 'Hijo de Neftalí', 'Nombre del hijo de Neftalí y del clan que descendió de él (los jezeritas). Las tres apariciones abarcan desde la bajada patriarcal a Egipto hasta la peregrinación por el desierto y la retrospectiva del Cronista, mostrando cómo los marcos genealógicos vinculaban a los ancestros individuales con la identidad corporativa de la tribu. Las variaciones preposicionales simplemente reflejan contextos narrativos distintos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103503, 'spa', 'encender, prender fuego (Hifil)', 'encender, prender fuego (Hifil)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103505, 'spa', 'arder, incendiarse (Qal)', 'arder, incendiarse (Qal)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103506, 'spa', 'ser quemado, ser encendido (Nifal)', 'ser quemado, ser encendido (Nifal)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103525, 'spa', 'Lagar / cuba de vino', 'Lagar / cuba de vino: una pila o cuba excavada en la roca para recibir el jugo de uva pisada en la prensa superior (גַּת), utilizada tanto como sustantivo común para la instalación física como ocasionalmente como topónimo. Se empareja con la era como señal de prosperidad en la cosecha (Dt 15:14; 16:13; Os 9:2; Jl 2:24) y con el גַּת en pasajes sobre la construcción de viñedos (Is 5:2; Jl 4:13). Los lagares desbordantes son signo de bendición divina (Pr 3:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103539, 'spa', 'Arder, encenderse', 'El sentido verbal de arder o ser encendido, abarcando Qal, Hophal y conjugaciones afines. Levítico 6:9, 12-13 prescribe el fuego perpetuo del altar que ''se mantendrá ardiendo'' (tuqad). Deuteronomio 32:22 e Isaías 10:16 emplean la raíz para la ira divina que arde de forma inextinguible. Isaías 65:5 describe el desagrado de Dios como un fuego ''que arde todo el día''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103543, 'spa', 'Hogar, fogón', 'Derivado nominal, yaqud, que significa ''hogar'' o ''lugar de fuego'', el sitio donde se mantiene encendida la llama. Isaías 30:14 usa miyaqud (''del hogar'') en un vívido símil: la destrucción de Jerusalén será tan completa que no quedará ni un tiesto suficientemente grande para recoger brasas del fogón. Este sentido concreto y doméstico designa un lugar fijo de combustión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103545, 'spa', 'Arder, ardiente', 'Participio arameo que significa ''ardiente'', usado exclusivamente en Daniel 3 (vv. 6, 11, 15, 17, 20, 21, 23, 26) para describir el horno abrasador de Nabucodonosor. La forma participial femenina (yaqidta) modifica al sustantivo del horno, enfatizando su estado de combustión continua. La evidencia multilingue — español ''ardiente'', francés ''ardente'' — refleja uniformemente la combustión activa y permanente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103551, 'spa', 'Totalidad de lo existente', 'La totalidad colectiva de las cosas vivas y existentes. En el relato del diluvio, ''todo lo existente'' abarca a toda criatura con aliento de vida, subrayando la casi total reversión de la creación. En Deuteronomio designa el séquito y las posesiones de los líderes rebeldes. Las glosas multilingües oscilan entre ''existencia'' (enfatizando el ser) y ''ser viviente'' (enfatizando la vida concreta).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103553, 'spa', 'Cazador de aves', 'Quien atrapa aves profesionalmente usando lazos, redes y señuelos. En los tres contextos, el pajarero representa amenaza y entrampamiento, ya sea por enemigos humanos reales o por peligros espirituales. La imagen es poderosa porque la caza de aves requiere astucia paciente y oculta: el pájaro no percibe el peligro hasta quedar atrapado. Los malvados de Jeremías ''acechan como pajareros'' para atrapar personas en sus maquinaciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103555, 'spa', 'Nombre propio Joctán', 'El nombre propio Yoqṭān (יָקְטָן), hijo de Heber y descendiente de Sem, ancestro de trece grupos tribales árabes. Su genealogía en la Tabla de las Naciones (Gn 10:25, 26, 29) y su paralelo en Crónicas (1 Cr 1:19, 20, 23) traza los pueblos semíticos del sur de Arabia y Yemen. La tradición árabe preserva su memoria como Qaḥṭān, progenitor de los ''árabes del sur''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103560, 'spa', 'Nombre personal judahíta', 'Nombre personal de la tribu de Judá que invoca la acción establecedora de Yahvé. Su aparición en la línea de Jeconías (1 Crónicas 3:18) lo vincula a la familia real exiliada, convirtiéndolo en un marcador significativo dentro del hilo genealógico que los primeros cristianos trazarían hasta Jesús. La doble aparición en 2:41 puede deberse a una repetición escribal o a dos individuos distintos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103563, 'spa', 'Ciudad cananea-levítica', 'Ciudad fortificada en la región del Carmelo que pasó del dominio cananeo a formar parte de la asignación tribal de Zabulón y finalmente a ser ciudad levítica. Su ubicación estratégica cerca del Carmelo y en el corredor de Jezreel le confería importancia para el control de rutas comerciales y militares de la región.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103564, 'spa', 'Alienarse, dislocarse (Qal)', 'Ser dislocado físicamente o enajenado emocionalmente (Qal): algo arrancado de su lugar apropiado. Génesis 32:25 lo usa para la cadera de Jacob desencajada durante la lucha en Peniel. Jeremías 6:8 y Ezequiel 23:17-18 lo extienden metafóricamente: el alma ''se aparta'' o ''se enajena'' de alguien. Los cognados árabes confirman tanto la dislocación física como la alienación emocional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103565, 'spa', 'Colgar, empalar (Hifil)', 'Colgar o empalar públicamente como forma de ejecución judicial (Hifil causativo). En Números 25:4, Dios ordena a Moisés ''colgar'' a los jefes ante el SEÑOR; en 2 Samuel 21:6 y 21:9, los gabaonitas ejecutan así a los descendientes de Saúl. El método exacto sigue debatiéndose: la Septuaginta sugiere exposición solar, el Targum crucifixión, y algunos cognados árabes sugieren arrojar desde una altura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103570, 'spa', 'Los colgados (Hofal)', 'Los que fueron colgados o empalados (participio pasivo Hofal): el resultado de la acción del Hifil, designando a los ejecutados. En 2 Samuel 21:13, se recogen los huesos de ''los colgados'' para sepultarlos junto a Saúl y Jonatán. El árabe al-mu''allaqīn (''los suspendidos'') emplea el participio pasivo correspondiente. Esta única aparición en Hofal trata la palabra como sustantivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103571, 'spa', 'Despertar del sueño (Qal)', 'Despertar o salir del sueño, marcando la transición de la inconsciencia al estado de alerta, frecuentemente en momentos de gran carga narrativa. Noé despierta y descubre el acto de Cam (Gn 9:24), Jacob despierta en Betel con una revelación teofánica (Gn 28:16), Faraón despierta de sueños proféticos (Gn 41:4, 7, 21), Sansón despierta sin saber que su fuerza lo ha abandonado (Jue 16:14, 20) y Salomón despierta tras su sueño en Gabaón (1 R 3:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103575, 'spa', 'Ser precioso o valioso', 'Ser precioso, preciado o tenido en alta estima (Qal). Se aplica a personas, nombres y vidas consideradas valiosas. El salmista se maravilla de que los pensamientos de Dios son «preciosos» más allá de toda cuenta (Sal 139:17), mientras que el precio de redimir un alma es «demasiado costoso» para pagarse (Sal 49:8). Expresa un sentido de valor intrínseco y honor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103577, 'spa', 'Hacer raro o escaso', 'Hacer raro, escaso o infrecuente (Hifil causativo). Dios amenaza con hacer a los humanos más raros que el oro de Ofir (Is 13:12), transformando la preciosidad en escasez. Proverbios 25:17 lo emplea de modo práctico: haz raras tus visitas para que tu vecino no se hastíe. Representa el cambio causativo de «ser valorado» a «ser hecho poco común».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103582, 'spa', 'Ser tasado a un precio', 'Ser tasado o valorado a un precio determinado (Qal con matiz monetario). Zacarías 11:13 lo emplea con fuerte sarcasmo: el pastor-profeta es «valorado» en treinta piezas de plata, el precio de un esclavo corneado (Éx 21:32). Resalta la dimensión de tasación comercial, distinta de la estima general del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103585, 'spa', 'Honor, estima, gloria', 'Honor, estima, gloria: el sentido abstracto de honor, estima o gloria — la cualidad de ser públicamente valorado y respetado. Ester usa este sentido repetidamente: el esplendor de la majestad del rey (Est 1:4), el honor que Amán desea para sí mismo (Est 6:6-9) y el honor otorgado a Mardoqueo (Est 6:3, 11). El Salmo 49:13, 21 reflexiona sobre el honor humano que no perdura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103587, 'spa', 'Cosa preciosa, tesoro', 'Cosa preciosa, tesoro: el sentido concreto de cosas preciosas, objetos de valor o tesoro — bienes tangibles de gran valía. Jeremías lamenta que todas las cosas preciosas de Jerusalén serán saqueadas (Jer 20:5), y Ezequiel denuncia a los líderes que se apoderan de tesoros y objetos preciosos (Ez 22:25). Job celebra el ojo del minero que descubre toda cosa preciosa bajo tierra (Job 28:10). Proverbios 20:15 empareja יְקָר con el oro y los rubíes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103591, 'spa', 'Precio, valor monetario', 'Precio, valor monetario: el sentido evaluativo de precio o valor monetario — el valor asignado a algo en una transacción. Zacarías 11:13 emplea יְקָר con devastadora ironía cuando el SEÑOR dice ''el espléndido precio en que fui valorado por ellos'', refiriéndose a las treinta piezas de plata. Es el uso más infrecuente, apareciendo solo en este único pasaje profético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103593, 'spa', 'Gloria y honor', 'Sustantivo masculino arameo que significa honor, gloria o esplendor (יְקָר), cognado del hebreo yaqar (precioso, de peso). En Daniel describe consistentemente la dignidad y magnificencia real: otorgada a Nabucodonosor por Dios (Dn 2:37; 5:18), prometida como recompensa (Dn 2:6), quitada y restaurada (Dn 4:33, 36; 5:20), y atribuida al dominio eterno del Hijo del Hombre (Dn 7:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103597, 'spa', 'precioso, costoso, valioso', 'precioso, costoso, valioso');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103604, 'spa', 'honrado, estimado (de personas)', 'honrado, estimado (de personas)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103605, 'spa', 'raro, escaso', 'raro, escaso');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103607, 'spa', 'Ser atrapado (Nifal/Pual)', 'Sentido pasivo del Nifal y Pual: ser enlazado, atrapado o cogido en una trampa. El sujeto es la víctima y no el cazador. Deuteronomio 7:25 advierte a Israel que no codicie el oro de los ídolos ''para que no seas enredado'' (פֶּן־תִּוָּקֵשׁ בּוֹ), y Proverbios 6:2 describe quedar atrapado por las propias palabras imprudentes. Isaías 8:15 y 28:13 lo usan para quienes tropezarán y ''serán atrapados'' bajo el juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103609, 'spa', 'Poner trampa (Qal)', 'Sentido activo del Qal: tender un lazo, poner una trampa o actuar como cazador. El sujeto es quien deliberadamente coloca la trampa. En Jeremías 50:24 Dios habla como cazador divino: יָקֹשְׁתִּי לָךְ (''te puse trampa''), y Babilonia fue atrapada sin saberlo. Salmo 141:9 describe a los impíos que ''tienden lazos'' para el justo, y Salmo 124:7 retrata a ''los cazadores'' (יוֹקְשִׁים) de cuya trampa Israel escapó.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103614, 'spa', 'Hijo de Abraham', 'Jocsán es identificado de manera consistente como hijo de Abraham por Cetura y padre de Seba y Dedán (Gn 25:2, 3; 1Cr 1:32, apareciendo dos veces en el pasaje de Crónicas). La Septuaginta traduce el nombre como Ιεξαν o Ιεκταν, mostrando los intentos griegos de representar las consonantes hebreas. Las glosas multilingües preservan aproximaciones fonéticas del nombre original.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103616, 'spa', 'temer, tener miedo (Qal)', 'La acepción dominante (239 apariciones): miedo visceral o pavor provocado por peligro, enemigos o teofanías divinas. Variante formal del sentido 1, que cubre la misma gama semántica de alarma involuntaria atestiguada por la fórmula recurrente ''no temas'' a lo largo de toda la Biblia hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103623, 'spa', 'temible, terrible (Nifal)', 'Participio Nifal con función adjetival (44 apariciones): describe a Dios, su nombre, sus obras o lugares sagrados como imponentes y terribles. La exclamación de Jacob ''¡Cuán temible es este lugar!'' (Gn 28:17) y ''terrible en alabanzas'' del Cántico del Mar (Éx 15:11) son casos paradigmáticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103626, 'spa', 'reverenciar, temer a Dios (Qal)', 'Temor reverencial hacia Dios o la autoridad soberana (25 apariciones): la postura piadosa y sostenida de adoración y obediencia, distinta del miedo momentáneo. El árabe ittaqa y khashiya captan este registro devocional. Mandatos como ''Temerás al SEÑOR tu Dios'' (Dt 6:13) representan la reverencia ética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103635, 'spa', 'temeroso de Dios (adj./ptc.)', 'Adjetivo o participio sustantivado (14 apariciones) que designa a una persona caracterizada por la piedad temerosa de Dios: ''el que teme al SEÑOR''. Retratos clave incluyen la autoidentificación de José (Gn 42:18) y la reputación de Abdías (1 R 18:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103653, 'spa', 'amedrentar, aterrorizar (Piel)', 'Piel intensivo-causativo (5 apariciones): amedrentar, intimidar o aterrorizar deliberadamente a alguien. Las cinco apariciones se agrupan en contextos narrativos tardíos de intimidación política: la campaña de Sanbalat contra Nehemías (Neh 6:9, 14, 19) y la súplica de la mujer de Tecoa (2 S 14:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103699, 'spa', 'crux textual (Miq 6:9)', 'Una única aparición en Miqueas 6:9 donde la evidencia textual y de las versiones es ambigua: algunas tradiciones leen yir''eh (''verá'') en lugar de yira'' (''temerá''). Las glosas multilingües se dividen entre ''verá'' y ''temerá'', reflejando una antigua dificultad en el texto consonántico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103716, 'spa', 'ser temido (Nifal, Sal 130:4)', 'Uso Nifal único en el Salmo 130:4, ''para que seas temido'', donde el perdón es el fundamento de la reverencia. Esta paradoja teológica —el perdón produciendo temor reverencial en vez de presunción— constituye la percepción central del salmo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103741, 'spa', 'Temeroso de Dios (singular)', 'Temeroso de Dios (singular): el uso adjetival singular que describe a un individuo como ''temeroso de Dios'' o ''el que reverencia a Dios'', con 15 ocurrencias concentradas en la caracterización narrativa. Job es presentado tres veces con este epíteto (Job 1:1, 1:8, 2:3), y Abraham se demuestra יְרֵא אֱלֹהִים en la Akedá (Gn 22:12). Abdías es descrito como ''muy temeroso de YHWH'' (1 R 18:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103742, 'spa', 'Los que temen (plural)', 'Los que temen (plural): el plural colectivo —''los que temen [a YHWH/Dios]''— que funciona como designación casi técnica de la comunidad piadosa, con 20 apariciones principalmente en los Salmos. En Sal 22:23 el salmista clama ''¡Vosotros los que teméis a YHWH, alabadle!'' y en Sal 33:18 el ojo de Dios está sobre ''los que le temen''. El francés ceux qui craignent y el español los que temen preservan la estructura participial-colectiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103747, 'spa', 'Para los que le temen (con lamed)', 'Para los que le temen (con lamed): la construcción prepositional dativa ''a/para los que le temen'', con 6 ocurrencias donde el prefijo lamed crea un marco benefactivo. Sal 25:14 declara ''el secreto de YHWH es para los que le temen''; Sal 31:19 se maravilla de la bondad ''guardada para los que te temen''. El español a los que le temen y el alemán fur jene furchtend traducen fielmente la estructura ''para beneficio de''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103749, 'spa', 'Temor (uso nominal)', 'Temor (uso nominal): un uso nominal o abstracto donde la forma funciona como el sustantivo ''temor'' o ''reverencia'' en vez de describir a una persona, con 3 ocurrencias. En Is 29:13 el ''temor de mí'' del pueblo (יִרְאָתָם) se ha vuelto mero mandamiento rutinario, y en Jon 1:10 y 1:16 los marineros ''temieron con gran temor''. El paso de lo adjetival a lo nominal queda confirmado por el español temor como sustantivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103750, 'spa', 'Temeroso, con miedo', 'Temeroso, con miedo: el sentido de temor emocional, con 10 apariciones en contextos de ansiedad y terror humano. En Dt 20:8 los oficiales preguntan ''¿quién es temeroso y de corazón apocado?'' antes de la batalla; en Gn 32:11 Jacob confiesa ''tengo miedo'' antes de encontrarse con Esaú. Jue 7:3 emplea la misma expresión de temor ante la batalla. El español temeroso refleja la dificultad de distinguir morfológicamente entre la reverencia y el pavor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103772, 'spa', 'temor reverencial de Dios', 'temor reverencial de Dios');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103776, 'spa', 'miedo o pavor', 'miedo o pavor');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103784, 'spa', 'temible, imponente', 'temible, imponente');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103795, 'spa', 'Jerobaal (nombre de Gedeón)', 'El nombre propio Jerobaal (''que Baal contienda''), dado a Gedeón tras demoler el altar de Baal en Ofra (Jue 6:32). Usado a lo largo del ciclo de Gedeón-Abimelec (Jue 7:1; 8:29, 35; 9:1-57) y en el discurso de despedida de Samuel (1 S 12:11). Las 14 apariciones se refieren a un solo individuo. La variante Jeroboset (2 S 11:21) sustituye ba''al por boshet.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103797, 'spa', 'Jeroboam (nombre propio)', 'Nombre propio masculino Yarovam (Jeroboam), que significa ''el pueblo se multiplica'', y designa a dos reyes del norte de Israel. Jeroboam I hijo de Nabat (unas 90 apariciones) lideró la secesión del norte e instituyó el culto a los becerros en Dan y Betel, convirtiéndose en el rey pecador paradigmático de la retórica deuteronomista (1 R 15:30; 2 R 17:21). Jeroboam II hijo de Joás (unas 14 apariciones) expandió las fronteras bajo la profecía de Jonás.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103805, 'spa', 'bajar, descender (Qal)', 'La acepción dominante del Qal (242 apariciones) cubre todas las formas verbales finitas de personas o grupos que descienden físicamente de montañas, entran en valles o viajan a ciudades de menor elevación. Las glosas interlingüísticas preservan el vector espacial: descendió, bajó, ging hinab.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103809, 'spa', 'los que descienden (ptc./sust.)', 'Participio activo Qal sustantivado (44 apariciones), especialmente en la fórmula ''yorde bor'' (los que descienden a la fosa/Seol). Variante formal del sentido 3, cubriendo la misma expresión formularia de la literatura poética y profética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103823, 'spa', 'fluir, correr (líquidos)', 'Quince pasajes emplean yarad Qal con sujetos líquidos en movimiento: lágrimas que corren por el rostro (Lm 3:48), aceite que baja por la barba (Sal 133:2), agua o lluvia que desciende. La flexibilidad del verbo con sujetos líquidos pone de relieve su semántica espacial central.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103825, 'spa', 'hacer descender (Hifil)', 'El causativo Hifil (53 apariciones) traslada la agencia: hacer bajar a alguien o algo desde un lugar más alto. Incluye Génesis 24:18 (bajar un cántaro), 37:25 (llevar a José a Egipto), 42:38 (hacer bajar a Benjamín). Las traducciones reflejan uniformemente la morfología causativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103843, 'spa', 'enviar abajo (Hifil figurado)', 'El Hifil con sujetos abstractos o divinos (13 apariciones) expresa enviar lluvia, hacer caer juicio o humillar a alguien (1 S 2:6). Esta extensión figurada del causativo mantiene la metáfora espacial añadiendo peso evaluativo o teológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103861, 'spa', 'ser hecho descender (Hofal)', 'El Hofal pasivo (6 apariciones) marca entidades hechas descender involuntariamente: Génesis 39:1 (José llevado a Egipto), Isaías 14:11/15 (el rey bajado al Seol), Ezequiel 31:18. Las traducciones reflejan la morfología pasiva: fue bajado, was brought down.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103870, 'spa', 'caer, derrumbarse', 'Tres pasajes aplican yarad Qal a estructuras o murallas que caen o se derrumban: Deuteronomio 20:20, 28:52 (contextos de asedio), Isaías 32:19 (el bosque que cae). El verbo espacial se extiende naturalmente al colapso vertical, y las traducciones lo vierten como ''caer'' o ''derrumbarse''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103920, 'spa', 'al descender (infinitivo constructo)', 'Cuatro casos emplean el infinitivo constructo Qal con preposiciones (be-, mi-, le-) para formar cláusulas temporales o adverbiales: ''cuando descendió'' (Éx 34:29), ''de descender'' (Gn 46:3). Esta función gramatical sirve a la cohesión discursiva más que a introducir un nuevo sentido léxico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103985, 'spa', 'lectura incierta (2 S 18:4)', 'Una única aparición dudosa en 2 Samuel 18:4, donde las traducciones divergen significativamente (salieron, went out, alla dehors), lo que sugiere posible corrupción textual o un uso idiomático raro. La glosa ''salieron'' contrasta con la direccionalidad descendente esperada de yarad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (103998, 'spa', 'Yered (nombre propio)', 'Nombre propio masculino Yered (יֶרֶד), que significa ''descenso'' (de yarad, descender), referido principalmente al patriarca antediluviano que engendró a Enoc a los 162 años y vivió hasta los 962 (Gn 5:15-20; 1 Cr 1:2). Un segundo portador aparece en la genealogía de Judá (1 Cr 4:18). La tradición española emplea las formas ''Jared'' o ''Jered''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104000, 'spa', 'río Jordán (nombre propio)', 'Nombre propio del río principal de Palestina, que fluye hacia el sur desde el mar de Galilea hasta el mar Muerto. Aparece casi siempre con artículo (ha-Yarden) en la prosa. Sus cruces marcan momentos decisivos: la entrada de Israel en Canaán (Jos 3-4), disputas fronterizas tribales (Jue 12:5-6) y actos proféticos (2 R 5:10-14). El nombre se conserva prácticamente sin cambios en todas las lenguas receptoras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104015, 'spa', 'Disparar flechas', 'Disparar flechas o proyectiles, usado tanto en el infinitivo Qal (2 Cr 26:15, ''para disparar flechas'') como en el imperfecto y participio Hifil (2 S 11:24, ''y dispararon'' contra los defensores; 1 S 31:3 = 1 Cr 10:3, ''los flecheros'' que hirieron a Saúl). La forma participial hammorim designa arqueros profesionales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104019, 'spa', 'Ser regado, saturado', 'Pasivo Hofal que significa ser regado o saturado, presente únicamente en Proverbios 11:25: ''el alma generosa será prosperada, y el que riega será también regado (yoreh).'' Este sentido pasivo de empapar o regar está semánticamente distante del sentido de disparar. La imagen agrícola transmite la bendición recíproca de la generosidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104022, 'spa', 'Enseñar, instruir (Hifil)', 'Enseñar, instruir (Hifil): el sentido dominante en Hifil: enseñanza e instrucción formal. El árabe عَلَّمَ (enseñar), el coreano 가르치다 y el suajili -fundisha convergen en la transmisión pedagógica. Dios enseña a Moisés qué decir (Éx 4:12) y los sacerdotes levíticos enseñan a Israel los estatutos (Lv 10:11). El sustantivo torá deriva directamente de este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104024, 'spa', 'Disparar flechas (Qal/Hifil)', 'Disparar flechas (Qal/Hifil): Qal y Hifil para el disparo de flechas o proyectiles. El árabe رَمَى (lanzar/disparar) y el coreano 쏘다 (disparar) confirman la imagen balística. El disparo de flechas de Jonatán en 1 S 20:20-36 es la pieza narrativa central. Éx 19:13 advierte que los transgresores del Sinaí ''ciertamente serán atravesados''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104031, 'spa', 'Maestro (participio Hifil', 'Maestro (participio Hifil: מורֶה): el participio Hifil sustantivado moreh, que significa ''maestro''. El árabe مُعَلِّم y el suajili mwalimu (maestro) reflejan el mismo patrón de sustantivo de agente. Aparece en 2 R 17:28 (un sacerdote-maestro), Pr 5:13 (mis maestros) e Is 9:15 (falsos maestros). La forma tiende un puente entre el verbo y el rol social.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104033, 'spa', 'Arrojar, lanzar, tirar (Qal)', 'Arrojar, lanzar, tirar (Qal): Qal para arrojar o lanzar objetos que no son flechas: cuerpos al mar (Éx 15:4), una piedra memorial colocada en su sitio (Gn 31:51), o Job arrojado al lodo (Job 30:19). El árabe وَرَى y el español arrojó distinguen este sentido del de la arquería más precisa por la variedad de objetos lanzados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104035, 'spa', 'Arquero, tirador (sustantivo)', 'Arquero, tirador (sustantivo): el participio sustantivado como ''arquero'' o ''tirador'', siempre en plural con artículo: los arqueros que hirieron a Saúl (1 S 31:3, 1 Cr 10:3) y a Josías (2 Cr 35:23). El español los arqueros y el coreano 궁수들 confirman la designación militar profesional. El contexto es uniformemente narrativa de campo de batalla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104038, 'spa', 'Mostrar, señalar, dirigir (Hifil)', 'Mostrar, señalar, dirigir (Hifil): un sentido extendido del Hifil: mostrar, señalar o dirigir el camino a alguien. Jacob envía a Judá por delante para ''señalar el camino'' hacia Gosén (Gn 46:28); Dios muestra a Moisés un árbol para sanar el agua amarga (Éx 15:25). El español mostró y el árabe أرشد (guiar) destacan la orientación más que la instrucción de aula.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104053, 'spa', 'Enviar lluvia (Hifil)', 'Enviar lluvia (Hifil): un uso raro del Hifil que significa enviar lluvia o dar la lluvia temprana, posiblemente vinculado a la imagen de ''arrojar hacia abajo'' de la raíz. Os 6:3 y 10:12 lo emplean para Dios haciendo llover justicia. El español llueva (''que llueva'') y el sustantivo יוֹרֶה (lluvia temprana) conectan con esta extensión agrícola-meteorológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104075, 'spa', 'Ser arrojado, ser atravesado (Qal pasivo)', 'Ser arrojado, ser atravesado (Qal pasivo): una forma pasiva del Qal en Éx 19:13 que especifica que el transgresor del Sinaí ''ciertamente será arrojado/atravesado'' (apedreado o traspasado). El español será arrojado confirma el contexto de ejecución judicial. Se superpone con el sentido 2 pero lleva una fuerza distintivamente punitiva y pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104093, 'spa', 'Jerusalén (ciudad)', 'El nombre propio יְרוּשָׁלַ͏ִם, que designa la ciudad que sirvió como capital política de la monarquía unida de David y del reino de Judá, y como centro cultual donde se erigió el Templo. Las 643 ocurrencias —incluidas formas direccionales, locativas y ablativas— se refieren a esta única ciudad. Registrada en fuentes asirias como Urusalim y en las cartas de Amarna.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104113, 'spa', 'El nombre propio de Jerusalén en su ortografía aramea, usado en las secciones ar', 'El nombre propio de Jerusalén en su ortografía aramea, usado en las secciones arameas de Esdras y Daniel. En Esdras 4-7 aparece en la correspondencia oficial persa sobre la reconstrucción de la ciudad, frecuentemente precedido de preposiciones (''en Jerusalén'', ''a Jerusalén''). En Daniel evoca la ciudad como la dirección de oración judía (Dn 6:11) y como origen de los utensilios del templo profanados por Belsasar (Dn 5:2-3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104119, 'spa', 'mes', 'El sentido temporal ''mes,'' usado como unidad de tiempo calculada por el ciclo lunar. Aparece tanto en cadenas constructas que nombran meses específicos del calendario (1 R 6:37 ''el mes de Ziv,'' 1 R 6:38 ''el mes de Bul,'' 1 R 8:2 ''el mes de Etanim'') como en formas plurales que miden duraciones (''meses de vacuidad,'' Job 7:3; ''meses de antaño,'' Job 29:2; ''tres meses,'' Éx 2:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104123, 'spa', 'luna', 'El sentido astronómico de ''luna'' como cuerpo celeste visible, distinto del sinónimo más común יָרֵחַ (H3394). En Deuteronomio 33:14, el plural ''lunas'' se refiere a la cosecha agrícola que los ciclos lunares producen. Isaías 60:20 usa el singular con sufijo posesivo (''tu luna'') en la promesa escatológica de que la luna no se ocultará más.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104130, 'spa', 'La luna como cuerpo celeste visible, contraparte nocturna del sol', 'La luna como cuerpo celeste visible, contraparte nocturna del sol. Aparece en tres agrupaciones temáticas principales: (a) cosmológica, como parte del orden creado por Dios junto con el sol y las estrellas (Gn 37:9; Sal 136:9; Jos 10:12-13); (b) cultual, como objeto de adoración ilícita condenada en Deuteronomio 4:19, 17:3, 2 Reyes 23:5 y Jeremías 8:2; (c) escatológica, oscurecida o ensangrentada en visiones proféticas del Día del Señor (Jl 3:4; Is 13:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104136, 'spa', 'Yerojam (nombre propio)', 'Nombre propio masculino que significa ''que le sea mostrada compasión'', portado por al menos seis individuos distintos: el abuelo de Samuel, el efratita (1 S 1:1; 1 Cr 6:27, 34), jefes de clan benjaminitas (1 Cr 8:27; 9:8), figuras sacerdotales en Jerusalén (1 Cr 9:12; Neh 11:12), un guerrero davídico (1 Cr 12:7), un líder danita (1 Cr 27:22) y un capitán que ayudó a entronizar a Joás (2 Cr 23:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104138, 'spa', 'Yerajmeel', 'El nombre propio Yerajmeel (Yerachme''el), que significa ''que Dios tenga compasión'', llevado por tres figuras del AT: (1) un ancestro prominente de un clan judahíta (1 Cr 2:9, 25-42), (2) un levita (1 Cr 24:29) y (3) un oficial real bajo Joacim (Jer 36:26). El español ''Yerajmeel'' conserva las consonantes guturales del hebreo original.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104145, 'spa', 'Adversario en litigio', 'Oponente o contendiente que presenta acusaciones o disputas contra alguien. El matiz jurídico, proveniente de רִיב (entablar un pleito), indica que se trata de adversarios que cuestionan los derechos de uno, no simplemente enemigos militares. El salmista y los profetas apelan a Dios como juez supremo para que asuma su causa frente a estos litigantes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104146, 'spa', 'Nombre de abogacía divina', 'Nombre propio que invoca la defensa o intercesión divina. La aparición simeonita muestra un uso antiguo, mientras que las referencias en Esdras conectan el nombre con la crisis de identidad comunitaria tras el exilio, apropiado para un nombre que significa «él contiende», ya que la comunidad postexílica luchaba por definir sus límites.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104148, 'spa', 'Jefe levítico', 'Nombre de un líder levítico conservado en los registros de Crónicas sobre la organización del templo. La alternancia entre la forma larga (-yahu) y la abreviada (-yah) del sufijo teofórico es habitual en los nombres hebreos. Como jefe de un turno levítico, Yeriyahu tenía la responsabilidad de organizar las rotaciones del servicio en el templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104149, 'spa', 'Jericó (nombre de lugar) — La antigua ciudad del valle del Jordán, que aparece e', 'Jericó (nombre de lugar) — La antigua ciudad del valle del Jordán, que aparece en tres variantes ortográficas que reflejan la tradición escribal. Es conocida sobre todo como el sitio de la dramática conquista de Josué (Jos 6:1-21), pero también sirve como centro profético bajo Eliseo (2 Re 2:4-5) y como punto de referencia en la captura de Sedequías (Jer 39:5). En español Jericó, en francés y en alemán Jericho preservan el topónimo de manera uniforme.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104156, 'spa', 'Yerimot (nombre propio)', 'Nombre propio masculino que aparece en variantes ortográficas (יְרֵימוֹת / יְרֵמוֹת / יְרִימוֹת), que significa ''alturas'' o ''él es exaltado.'' La Septuaginta lo traduce variadamente como Ιεριμουθ y Αρειμωθ. Se refiere a al menos diez individuos: descendientes benjaminitas de Bela (1 Cr 7:7-8; 8:14), músicos levíticos asignados por suerte (1 Cr 25:4, 22), un jefe tribal de Neftalí (1 Cr 27:19) y un hijo de David (2 Cr 11:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104163, 'spa', 'Cortina, panel de tela — Una cortina o panel de tela, particularmente las franja', 'Cortina, panel de tela — Una cortina o panel de tela, particularmente las franjas tejidas que formaban las paredes del tabernáculo o la cubierta de una tienda. Este uso abarca casi todas las apariciones (53 veces). Solo las instrucciones del tabernáculo en Éxodo 26 lo emplean más de 30 veces. En español «la cortina», en francés «le rideau» y en alemán «der Vorhang» traducen el sentido textil. Fuera del tabernáculo, el término aparece en contextos figurados: Sal 104:2 compara los cielos con una cortina extendida por Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104169, 'spa', 'Tienda, morada — Por metonimia, la tienda o morada formada por cortinas, refirié', 'Tienda, morada — Por metonimia, la tienda o morada formada por cortinas, refiriéndose a la habitación misma en lugar de su tela. En 2 Sam 7:2, David dice que el arca de Dios «habita entre cortinas», es decir, dentro de una tienda-morada. Aquí el material (cortinas) representa toda la estructura. En español «la tienda» interpreta correctamente la metonimia. El peso teológico es significativo: la incomodidad de David ante que Dios more en cortinas mientras él vive en un palacio de cedro impulsa el deseo de construir el templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104178, 'spa', 'muslo, pierna superior', 'muslo, pierna superior');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104179, 'spa', 'lado, flanco', 'lado, flanco');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104189, 'spa', 'base, fuste (del candelabro)', 'base, fuste (del candelabro)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104196, 'spa', 'Los confines más alejados o los extremos últimos de un territorio geográfico', 'Los confines más alejados o los extremos últimos de un territorio geográfico. Jueces 19:1 sitúa a un levita en ''los confines de la montaña de Efraín'', e Isaías 14:13 habla de ascender a ''los lados del norte''. La forma dual enfatiza que se trata de los dos flancos exteriores de una región.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104197, 'spa', 'La sección trasera de una estructura construida, especialmente la pared posterio', 'La sección trasera de una estructura construida, especialmente la pared posterior del tabernáculo o del templo. Éxodo 26:22-27 emplea la forma dual repetidamente para las dos esquinas posteriores y los travesaños traseros del armazón del tabernáculo. Se trata siempre del extremo opuesto a la entrada, lo más profundo del interior de la estructura sagrada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104201, 'spa', 'El costado o flanco del cuerpo de una persona o de un territorio en un sentido m', 'El costado o flanco del cuerpo de una persona o de un territorio en un sentido más anatómico o fronterizo. Génesis 49:13 lo usa para el límite lejano de Zabulón que llega hasta Sidón — literalmente ''su costado hacia Sidón''. Este sentido preserva el vínculo más cercano con el sustantivo raíz ''muslo/lomo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104204, 'spa', 'Los recovecos más internos o las profundidades ocultas de un espacio cerrado com', 'Los recovecos más internos o las profundidades ocultas de un espacio cerrado como una cueva, la bodega de un barco o la fosa del Seol. En 1 Samuel 24:3 David se esconde en ''lo más profundo de la cueva'', e Isaías 14:15 envía al tirano caído a ''las profundidades de la fosa''. Evoca un espacio a la vez profundo y oculto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104219, 'spa', 'Yarmut (ciudad cananea)', 'Nombre propio de lugar Yarmut (יַרְמוּת), que designa principalmente una ciudad real cananea en la Sefela cuyo rey Piram se unió a la coalición anti-gabaonita derrotada por Josué (Jos 10:3, 5, 23; 12:11), asignada luego a Judá (Jos 15:35) y repoblada tras el exilio (Neh 11:29). Una segunda Jarmut en Isacar sirvió como ciudad levítica (Jos 21:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104223, 'spa', 'Jeremías (nombre propio)', 'El nombre propio Yirmeyahu/Yirmeyah, compuesto teofórico que probablemente significa «Yah exalta» o «Yah libera». Designa de manera abrumadora al profeta Jeremías de Anatot (Jer 1:1), cuyo ministerio abarcó desde el reinado de Josías hasta la caída de Jerusalén. Portadores secundarios incluyen al padre de Hamutal, esposa de Josías (2 Re 23:31), un guerrero gadita (1 Cr 12:13) y sacerdotes y líderes postexílicos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104231, 'spa', 'Temblar o afligirse', 'El verbo aparece en pasajes que describen temblor interior o angustia. Isaías retrata al guerrero moabita cuya ''alma tiembla dentro de él'' (Is 15:4) ante el juicio. El esposo de Ana pregunta: ''¿Por qué está afligido tu corazón?'' cuando ella llora por su esterilidad (1S 1:8). Joab advierte que las cosas ''irán mal'' si el enemigo de Absalón escapa (2S 20:6), y Job describe una calamidad que ''va mal'' para el impío.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104233, 'spa', 'Escupir como afrenta', 'Acto de escupir en el rostro de alguien como expresión ritual o legal de desprecio y vergüenza. Lejos de ser una simple grosería, el escupitajo en la cara marcaba una desgracia formal en el contexto bíblico, ya fuera como juicio divino (en el caso de Miriam) o como sanción comunitaria por incumplimiento de obligaciones familiares (el rechazo del levirato).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104234, 'spa', 'Verdor, vegetación verde', 'Vegetación verde, hierba o verdor como sustantivo colectivo o abstracto. En las ordenanzas de la creación, יֶרֶק עֵשֶׂב (''hierba verde'') designa el alimento vegetal dado a todas las criaturas (Gn 1:30) y luego extendido a la humanidad (Gn 9:3). La plaga de langostas consume todo יֶרֶק en Egipto (Éx 10:15). Balac teme que Israel devore el verdor del campo como un buey (Nm 22:4). En la poesía sapiencial, los malvados prosperan como hierba verde pero se marchitan rápidamente (Sal 37:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104240, 'spa', 'Hortalizas, verduras', 'Hierbas, hortalizas, verduras — término colectivo para plantas verdes comestibles cultivadas. Se usa en estado constructo con ''huerto'' (gan-yārāq) para designar un huerto de hortalizas en Dt 11:10 y 1 R 21:2. Proverbios 15:17 lo emplea en un dicho sapiencial que contrasta la comida humilde de verduras con un banquete opulento pero sin amor. En Isaías 37:27 la forma constructa describe brotes verdes frágiles, signo de vulnerabilidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104241, 'spa', 'Añublo, tizón agrícola', 'Enfermedad de los cultivos —añublo, tizón o moho— que destruye el grano y las cosechas, apareciendo siempre junto a שִׁדָּפוֹן (asolamiento/abrasamiento) en textos formularios de maldición y oración. Las cinco apariciones siguen este emparejamiento: Deuteronomio 28:22 en las maldiciones de la alianza, la oración de Salomón en el templo (1 R 8:37; 2 Cr 6:28), Amós 4:9 en el catálogo de advertencias ignoradas, y Hageo 2:17.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104243, 'spa', 'Palidez, ictericia facial', 'Palidez amarillenta enfermiza o ictericia del rostro humano, extendiendo la semántica cromática de la raíz desde cultivos enfermos a la complexión humana. Se encuentra únicamente en Jeremías 30:6, donde el profeta pregunta por qué todo hombre tiene las manos sobre sus lomos como mujer de parto y todos los rostros se han vuelto a יֵרָקוֹן. El español ''palidez'' traslada decisivamente el vocabulario agrícola al fisiológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104247, 'spa', 'Tonalidad verdosa diagnóstica', 'Un tono verde pálido o amarillento-verdoso, especialmente como señal diagnóstica de contaminación. En los códigos sacerdotales de pureza, las manchas verdosas indicaban impureza potencialmente contagiosa que requería cuarentena y escrutinio del sacerdote. El uso metafórico del Salmo para el destello del oro sugiere un verde-dorado luminoso más que una palidez enfermiza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104248, 'spa', 'Qal: tomar posesión territorial', 'El sentido Qal dominante (130 pasajes) describe la toma de posesión de un territorio, concentrado de manera abrumadora en las narrativas deuteronómicas y de conquista (62 veces en Deuteronomio, 13 en Josué). El verbo denota entrar, ocupar y asentarse en la tierra. Equivalentes interlingüísticos como el árabe imtalaka y el suajili -miliki confirman el eje semántico de apropiación territorial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104250, 'spa', 'Hifil: desposeer o expulsar', 'El Hifil causativo (61 ocurrencias) expresa la desposesión forzosa: expulsar a cananeos, amorreos u otros habitantes. Este sentido domina en contextos de conquista (Nm 14:24; 21:32; 33:52-53). El árabe طَرَدَ («expulsar»), el coreano 쫓아내다 y el suajili -fukuza confirman el desplazamiento causativo de poseer a desalojar al ocupante previo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104257, 'spa', 'Qal: heredar como sucesor', 'El Qal con sujetos humanos que heredan bienes o la bendición del pacto aparece 18 veces, especialmente en narrativas patriarcales (Gn 15:4-8; 21:10). Este sentido de sucesión familiar se alinea con el árabe يَرِثُ, el coreano 상속하다 y el suajili -rithi, todos términos específicos de herencia legítima por línea de parentesco.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104272, 'spa', 'Qal: desposeer personas', 'Cuatro pasajes en Qal tienen complemento directo personal (personas en vez de territorio): desposeer a los habitantes (Dt 2:12, 21-22; Jue 14:15). Aunque se trata del Qal, el solapamiento semántico con el Hifil de desposesión es evidente. Las traducciones reflejan el objeto personal: «los despojaron», «déposséda eux».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104274, 'spa', 'Participio Qal: heredero', 'El participio Qal usado como sustantivo (9 pasajes) designa a un heredero o poseedor: Gn 15:3 (Eliezer como heredero), Nm 36:8 (herederas), Is 65:9 (herederos de Judá). El árabe وارث, el coreano 상속자 y el suajili mrithi muestran una nominalización consistente del concepto de sucesión patrimonial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104293, 'spa', 'Hifil: dar en herencia', 'El Hifil con el sentido de «hacer heredar» o «dar en herencia» (4 veces) aparece en contextos donde Dios o un ser humano otorga territorio como legado: Esd 9:12 (herencia de los padres), Job 13:26 (heredar amarguras). El árabe أَوْرَثَ y el coreano 물려주다 respaldan esta lectura causativa de transmisión hereditaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104295, 'spa', 'Nifal: empobrecerse', 'El Nifal (4 pasajes) introduce un giro semántico notable: empobrecerse, caer en la indigencia. Gn 45:11 («para que no empobrezcas»), Pr 20:13, 23:21 y 30:9 usan el Nifal de יָרַשׁ para la penuria. El árabe يَفْتَقِرُ, el coreano 가난해지다 y el suajili kuwa maskini confirman esta extensión semántica reconocida: de la desposesión a la pobreza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104324, 'spa', 'Hifil: empobrecer (hapax)', 'Una sola ocurrencia incierta en 1 S 2:7: «el SEÑOR empobrece» (morish). La forma Hifil podría significar causar pobreza (en paralelo con «enriquece»), pero la vocalización y la transmisión textual son debatidas. Las traducciones lo vierten como «empobrece», lo cual encaja en el campo semántico del Nifal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104380, 'spa', 'Piel/Qal: infestar (hapax)', 'Dt 28:42 presenta otro hapax: «el grillo poseerá (yeyaresh) todos tus árboles». La forma Piel o variante es oscura. Las traducciones divergen: «poseerá», «possèdera», pero el contexto de plaga de langostas sugiere invadir o infestar más que heredar, una extensión metafórica de la posesión territorial aplicada al mundo natural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104384, 'spa', 'posesión, herencia', 'Propiedad territorial poseída como herencia, particularmente territorio otorgado por Dios. Predomina en los relatos de desposesión de Deuteronomio: el Seír de Edom (Dt 2:5, 12), Moab (2:9), Amón (2:19) y la asignación transjordana (3:20; Jos 1:15). También en Jueces 21:17 para la herencia de Benjamín, Jeremías 32:8 para un campo redimible y 2 Crónicas 20:11 para la tierra que Dios dio a Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104391, 'spa', 'hay, existe (existencial)', 'La partícula existencial estándar: «hay», «existe», afirmando que algo es o está presente — 129 ocurrencias en contextos declarativos, interrogativos, condicionales y conjuntivos. Jacob oye que «hay grano en Egipto» (Gn 42:1); el SEÑOR está en este lugar «y yo no lo sabía» (Gn 28:16). El francés il y a, el alemán es gibt y el español hay convergen en la misma fuerza existencial impersonal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104401, 'spa', 'cópula con sufijo pronominal', 'Usado con sufijos pronominales como cópula que predica algo de una persona concreta: «tú eres», «él es» — 8 ocurrencias en contextos condicionales y retóricos. En Gn 24:42 el siervo dice «si tú estás [yeshka] tratando con bondad»; en Dt 13:3 el SEÑOR prueba «si realmente [yeshkem] lo amáis». La forma sufijada transforma la partícula impersonal en una predicación personal directa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104409, 'spa', 'riqueza, sustancia (nominal)', 'Un uso nominal infrecuente que significa «riqueza, sustancia, algo real» — una sola ocurrencia en Pr 8:21 donde la Sabiduría declara «para hacer que los que me aman hereden יֵשׁ». Aquí la palabra no funciona como partícula sino como sustantivo concreto: posesión real y tangible. Las tradiciones de traducción divergen: el inglés vierte «substance», mientras que el contexto sapiencial exige un término de bienes auténticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104422, 'spa', 'Qal: habitar, morar', 'Sentido dominante del Qal: habitar, residir, morar. Cubre el asentamiento permanente y el participio sustantivado יֹשֵׁב, ''habitante(s) de''. Es fundamental en contextos de alianza: ''habitaréis en la tierra'' (Lv 25:18). Las traducciones multilingües convergen en vocabulario residencial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104441, 'spa', 'Qal: sentarse', 'Acción física de sentarse o estar sentado, diferenciada de habitar. Incluye sentarse a comer (Gn 27:19), ocupar un trono (1 R 1:46) y sentarse para juzgar. La evidencia interlingüística distingue claramente este sentido postural del uso residencial del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104466, 'spa', 'Qal: permanecer, quedarse', 'Permanecer, quedarse o esperar: un sentido temporal que carece de la permanencia del habitar. Abraham dice a sus siervos ''quedaos aquí con el asno'' (Gn 22:5). Los equivalentes en otras lenguas —como ''permanecer'' o ''quedarse''— captan esta cualidad transitoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104493, 'spa', 'Hifil: hacer habitar, asentar', 'Hifil (causativo): asentar a alguien, hacer habitar, hacer sentar. Dios levanta al pobre y lo sienta con príncipes (1 S 2:8). Idiomático para concertar un matrimonio (instalar a una mujer en el hogar). El árabe أَسْكَنَ presenta una derivación causativa paralela.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104541, 'spa', 'Nifal: ser habitado', 'Nifal (pasivo): ser habitado. Frecuente en oráculos proféticos sobre ciudades y tierras: ''las ciudades habitadas serán asoladas'' (Ez 12:20). El foco recae sobre el lugar y no sobre sus moradores, como confirman las traducciones pasivas en múltiples lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104617, 'spa', 'Hofal: ser asentado', 'Hofal (pasivo causativo): ser hecho habitar, ser asentado. La forma más rara, presente en el oráculo de Isaías contra los acaparadores de tierra (Is 5:8) y en la promesa de que las ciudades arruinadas ''serán habitadas'' (Is 44:26). Representa el doble pasivo del Hifil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104683, 'spa', 'Guerrero heroico davídico', 'Nombre propio heroico vinculado a la élite militar de David. Sea uno o dos individuos con el mismo nombre, Jasobeam representa el liderazgo militar que aseguró el reino davídico. Las complicaciones textuales con el pasaje paralelo de Samuel y las propuestas de leer Isbaal muestran cómo los nombres propios podían corromperse o alterarse deliberadamente, especialmente los que contenían ''Baal''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104686, 'spa', 'Nombre propio bíblico', 'Jasub es identificado como hijo de Isacar, dando su nombre al clan jasubita (Nm 26:24), con registros genealógicos paralelos en Crónicas que muestran variación textual entre Jasub (Qeré) y Jasib (Ketiv) en 1Crónicas 7:1. Un individuo distinto llamado Jasub aparece entre quienes habían tomado esposas extranjeras durante el exilio (Esd 10:29). La Septuaginta traduce el nombre como Ιασουβ.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104689, 'spa', 'Nombre propio bíblico', 'Isví hijo de Aser aparece en la genealogía de la familia de Jacob al descender a Egipto (Gn 46:17), dando su nombre al clan isvita en el censo del desierto (Nm 26:44), con registros paralelos en Crónicas (1Cr 7:30). Un segundo Isví aparece como hijo de Saúl (1S 14:49), aunque Crónicas lista a Is-boset/Esbaal en esta posición (1Cr 8:33; 9:39), sugiriendo una posible conexión textual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104691, 'spa', 'Nombre propio hebreo posexílico que significa ''él salva'', forma contraída de Yeh', 'Nombre propio hebreo posexílico que significa ''él salva'', forma contraída de Yehoshúa. Designa de manera más prominente al sumo sacerdote Jesúa hijo de Josadac, quien lideró la restauración del sacrificio tras el exilio (Esd 2:2; 3:2; Neh 12:1). También lo llevan un jefe de división sacerdotal (1 Cr 24:11), un administrador levítico bajo Ezequías (2 Cr 31:15) y varios nombres de clanes en el censo del retorno. La forma de la LXX, Iēsous, es idéntica a la empleada más tarde para Jesús de Nazaret.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104696, 'spa', 'Salvación, liberación — La salvación o liberación divina vista como una realidad', 'Salvación, liberación — La salvación o liberación divina vista como una realidad única y abarcadora: el acto de Dios que rescata del peligro, la angustia o los enemigos. Todas las lenguas convergen: esp. salvación, fr. salut, al. Heil. Moisés la proclama junto al Mar Rojo (Éx 14:13); el salmista se aferra a ella en Sal 62:2. La palabra tiende un puente entre el rescate externo y la esperanza espiritual interior, como en Gn 49:18 («Tu salvación espero, oh SEÑOR»).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104698, 'spa', 'Victorias, actos de liberación — Actos concretos y repetidos de liberación divin', 'Victorias, actos de liberación — Actos concretos y repetidos de liberación divina: victorias obradas por Dios, generalmente en la forma plural yeshu''ot. El español «salvaciones» y los equivalentes plurales en otras lenguas marcan este cambio del concepto abstracto a las hazañas enumerables. David alaba a Dios como quien da «grandes victorias (yeshu''ot) a su rey» (2 Sam 22:51; Sal 18:50), y el salmista las recuerda como fundamento de esperanza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104730, 'spa', 'Grafía alternativa יִשְׂחָק', 'En estos cuatro pasajes el nombre aparece en su grafía alternativa יִשְׂחָק en vez de la más común יִצְחָק: en Salmo 105:9 («el juramento que hizo a Isaac»), Jeremías 33:26 (prometiendo restauración a la descendencia de Abraham, Isaac y Jacob), y dos veces en Amós donde «los lugares altos de Isaac» y «la casa de Isaac» funcionan como designaciones poéticas del reino del norte, Israel (Amós 7:9, 16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104731, 'spa', 'Extender el cetro real', 'El acto específico de extender el cetro de oro como gesto de favor real que concede audiencia y clemencia. Este término hebreo tardío capta un protocolo cortesano persa que la narrativa de Ester convierte en eje dramático. La extensión del cetro transforma la muerte segura en audiencia graciosa, haciendo de este verbo el punto de inflexión de la arriesgada intercesión de Ester.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104732, 'spa', 'Isaí (padre del rey David)', 'Isaí (padre del rey David)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104736, 'spa', 'Yishshiyyah / Ishiya (nombre propio)', 'Nombre propio masculino יִשִּׁיָּה / יִשִּׁיָּהוּ, que significa ''YHWH prestará'' o ''Yah no olvida'', llevado por múltiples individuos: un guerrero benjaminita que se unió a David en Siclag (1 Cr 12:6), un jefe de Isacar (1 Cr 7:3), levitas coatitas en el servicio del templo (1 Cr 23:20; 24:21, 25) y un laico que despidió a su mujer extranjera (Esd 10:31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104741, 'spa', 'desierto, páramo (lugar específico)', 'El uso concreto, a menudo semi-propio, que designa regiones desérticas específicas, particularmente el desierto del Jesimón cerca del mar Muerto. Casi todas las apariciones llevan artículo definido, funcionando como referencia geográfica reconocible. Las narrativas de Samuel sitúan a David en ''el Jesimón'' como fugitivo (1 S 23:19, 24; 26:1, 3), mientras que Números lo localiza como panorama desde Pisga (21:20) y Peor (23:28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104747, 'spa', 'desolación, yermo (abstracto)', 'El sentido abstracto y poético de desolación y aridez total, desprovisto de especificidad geográfica. Deuteronomio 32:10 describe el hallazgo de Israel ''en un yermo aullante,'' donde el paralelismo con ''tierra desierta'' y ''páramo de aullidos'' subraya la fuerza evocadora y no locativa de la palabra. Isaías 43:19-20 lo emplea para el desierto que Dios transformará con ríos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104748, 'spa', 'Persona de edad avanzada', 'El término aparece cuatro veces en la poesía de Job describiendo a personas ancianas. Job declara que «entre los ancianos está la sabiduría» (Job 12:12), contrastando los largos años con el entendimiento. Recuerda cómo «los ancianos se levantaban» cuando él entraba en la asamblea (Job 29:8, opuesto a «los jóvenes»). Elihú explica su reticencia: «Ustedes son ancianos, y yo soy joven en días» (Job 32:6), y observa que aun «los canosos» comparten esa condición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104750, 'spa', 'Ser colocado o puesto', 'El estado pasivo de ser colocado o dispuesto en posición. En Génesis 24:33 la comida puesta ante el siervo marca el inicio de la hospitalidad y la negociación por el compromiso de Rebeca. La colocación de José en un ataúd (50:26) cierra solemnemente Génesis: el último patriarca reposa en Egipto en vez de la tierra prometida, preparando el escenario para el Éxodo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104751, 'spa', 'Tierra asolada', 'El verbo aparece en formas qal imperfecto y consecutivo describiendo la tierra que queda desolada. En Génesis, los hermanos de José temían que «la tierra quedara desolada» si no sembraban durante la hambruna (Gn 47:19). Ezequiel lo usa tres veces: «vuestros lugares altos serán desolados» (Ez 6:6), «la tierra quedará desolada» de habitantes (Ez 12:19), y «la tierra fue asolada» por el rugido de la leona (Ez 19:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104753, 'spa', 'Ismael (nombre propio) — El nombre propio Ismael, que significa ''Dios oye'', apli', 'Ismael (nombre propio) — El nombre propio Ismael, que significa ''Dios oye'', aplicado a varios individuos, principalmente al hijo de Abraham por medio de Agar (Gn 16:11-15; 17:18-26; 25:9-17), cuyo relato de nacimiento gira en torno a la escucha divina de la aflicción, y al hijo de Netanías que asesinó a Gedalías (Jer 40:8–41:18; 2 Re 25:23-25). Grupos menores designan a figuras benjaminitas, judías y sacerdotales (1 Cr 8:38; 2 Cr 19:11; Esd 10:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104761, 'spa', 'Ismaelita (gentilicio)', 'El adjetivo gentilicio ''ismaelita'', que designa a los descendientes de Ismael o miembros de su confederación comercial. Son conocidos principalmente como los mercaderes de caravanas que compraron a José (Gn 37:25, 27, 28; 39:1), y también se aplica a individuos como Jéter el ismaelita (1 Cr 2:17) y Obil el ismaelita, encargado de los camellos reales (1 Cr 27:30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104769, 'spa', 'Dormir o quedarse dormido — el sentido intransitivo básico del Qal que abarca to', 'Dormir o quedarse dormido — el sentido intransitivo básico del Qal que abarca todas las formas de sueño natural, incluido el uso participial y adjetival de ''durmiendo'' o ''dormido''. Con 17 ocurrencias, este sentido dominante abarca desde el acto fundacional de Dios al sumir a Adán en sueño (Gn 2:21) hasta Faraón durmiendo y soñando (Gn 41:5), Elías durmiendo bajo la retama (1 R 19:5) y el lamento de Job.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104771, 'spa', 'Hacer dormir a alguien, adormecer — un causativo del Piel que describe a una per', 'Hacer dormir a alguien, adormecer — un causativo del Piel que describe a una persona induciendo el sueño en otra. Solo 1 ocurrencia: Dalila ''lo hizo dormir sobre sus rodillas'' antes de llamar a un hombre para cortar el cabello de Sansón (Jue 16:19). Se distingue del sentido intransitivo por la construcción causativa explícita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104775, 'spa', 'Envejecer, volverse añejo o hacerse crónico — un sentido del Nifal donde ''dormir', 'Envejecer, volverse añejo o hacerse crónico — un sentido del Nifal donde ''dormir'' se extiende metafóricamente al envejecimiento o la vejez, describiendo cosas que han permanecido demasiado tiempo o condiciones que han persistido. Aparece en 3 ocurrencias: una enfermedad cutánea crónica frente a un brote reciente (Lv 13:11), productos almacenados que deben despejarse cuando llega la nueva cosecha (Lv 26:10) y la advertencia contra el estancamiento espiritual en la tierra (Dt 4:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104787, 'spa', 'Dormido, que duerme', 'Dormido, en estado de sueño — usado literalmente de personas en reposo natural (1 Sam 26:7, 12; 1 Re 3:20; Cnt 5:2) y figuradamente de la aparente inactividad divina (Sal 78:65; 1 Re 18:27, referido a Baal) y de los muertos que descansan en el polvo esperando la resurrección (Dn 12:2). Las traducciones multilingües — español dormido, francés dormant — tratan esto uniformemente como un único sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104794, 'spa', 'Viejo, añejo', 'Viejo, de larga data — aplicado a productos almacenados que se han guardado con el tiempo (Lv 25:22; 26:10; Cnt 7:14, donde se emparejan frutos ''viejos y nuevos'') y a estructuras establecidas como la ''Puerta Vieja'' de Jerusalén (Neh 3:6; 12:39) y el ''estanque viejo'' de Isaías (Is 22:11). Las traducciones — español añejas y lo viejo, francés ancien — convergen en un único sentido de antigüedad temporal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104800, 'spa', 'salvar, librar (Hifil activo)', 'Hifil causativo activo: salvar, librar o rescatar a alguien del peligro, los enemigos, la angustia o la opresión — el sentido más amplio con 156 ocurrencias. Dios salva a Israel en el mar Rojo (Éx 14:30), levanta jueces para salvarlos de sus enemigos (Jue 3:31; 7:7; 10:1) y promete liberación futura por medio de los profetas (Is 35:4; 45:22). Agentes humanos también «salvan» en contextos militares y de auxilio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104806, 'spa', 'salvador, libertador (participio)', 'Participio Hifil usado como sustantivo agentivo: «salvador», «libertador», «rescatador» — 28 ocurrencias. El moshia'' es quien efectúa la liberación, ya sea Dios mismo («Yo soy el SEÑOR tu Dios… fuera de mí no hay salvador», Os 13:4) o un campeón humano como Otoniel (Jue 3:9) o Ehud (Jue 3:15). El artículo o el sufijo posesivo marca típicamente el uso sustantivado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104815, 'spa', 'ser salvado (Nifal pasivo)', 'Nifal pasivo/reflexivo: ser salvado, ser librado, recibir o experimentar la salvación — 21 ocurrencias. Aquí el rescatado es el sujeto gramatical: «Israel es salvado por el SEÑOR con salvación eterna» (Is 45:17), «dichoso tú, Israel — ¿quién como tú, pueblo salvado por el SEÑOR?» (Dt 33:29). El Nifal captura la perspectiva del beneficiario del mismo acontecimiento que el Hifil describe desde el agente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104891, 'spa', 'salvación (uso nominal ambiguo)', 'Una sola ocurrencia ambigua en 2 S 10:11 donde Joab dice a Abisai: «Si los arameos son más fuertes que yo, tú me salvarás; y si los amonitas son más fuertes que tú, yo iré a salvarte». La evidencia multilingüe (español para salvación, francés pour salut) sugiere que los traductores lo trataron como construcción nominal o de propósito, posiblemente una variante textual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104911, 'spa', 'salvación, liberación', 'salvación, liberación');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104919, 'spa', 'seguridad, protección', 'seguridad, protección');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104926, 'spa', 'Nombre propio masculino', 'Nombre propio masculino derivado de la raíz ישע (''salvar''), llevado por cuatro individuos distintos en 1 Crónicas. En español se traduce ''Yisi'' y en inglés ''Yishi'' o ''Ishi''. La Septuaginta varía notablemente entre manuscritos (Ισεμιηλ, Ιεσει, Σεει), lo que indica fluidez textual temprana. Las cinco ocurrencias aparecen en genealogías tribales de Jerameel, Judá, Simeón y Manasés.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104927, 'spa', 'Yeshayahu / Isaías (nombre propio)', 'Yeshayahu / Isaías (nombre propio)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104931, 'spa', 'Nombre propio postexílico', 'Cuatro individuos distintos llevan este nombre en Crónicas, Esdras y Nehemías: un nieto de Zorobabel en la línea real davídica (1 Cr 3:21), un jefe de los hijos de Elam que regresó con Esdras de Babilonia (Esd 8:7), un jefe de los meraritas en tiempos de Esdras (Esd 8:19) y un benjaminita en la Jerusalén de Nehemías (Neh 11:7). La Septuaginta traduce el nombre de diversas formas como Ioseia, Hesaia y Ieseia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104932, 'spa', 'Piedra preciosa persa', 'Piedra preciosa de origen persa, probablemente de tipo jaspe o similar al jade, valorada por su belleza y rareza. Su inclusión tanto en las vestiduras sacerdotales como en la descripción profética del esplendor primordial la sitúa entre las gemas más preciadas de la economía del antiguo Oriente Próximo. Su condición de préstamo lingüístico indica que era un artículo de lujo importado, no originario de Canaán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104935, 'spa', 'El sentido estativo del Qal', 'El sentido estativo del Qal: ser recto, agradable o aceptable a los ojos de alguien — la expresión formulaica yashar be''eynay (''fue recto a sus ojos''). Sansón dice a sus padres que la mujer filistea ''es recta a mis ojos'' (Jue 14:3, 7); Saúl se complace cuando el matrimonio de David ''fue recto a sus ojos'' (1 Sam 18:20, 26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104938, 'spa', 'El causativo del Hifil', 'El causativo del Hifil: hacer que vaya recto, dirigir hacia adelante, allanar un camino. En el Salmo 5:8 el salmista pide a Dios que ''enderece tu camino delante de mí''; en Proverbios 4:25 el sabio ordena ''que tus ojos miren directamente hacia adelante''; en Isaías 45:2 Dios promete ''allanar los lugares escabrosos'' ante Ciro. El Hifil añade una fuerza causativa más intensa que el Piel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104941, 'spa', 'El sentido dinámico del Qal', 'El sentido dinámico del Qal: ir recto, moverse directamente en una dirección física sin desviarse. Las vacas que tiraban del arca ''fueron recto por el camino de Bet-semes'' (1 Sam 6:12), sin torcer a derecha ni a izquierda — una de las descripciones direccionales más vívidas de la Biblia hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104948, 'spa', 'El factitivo del Piel', 'El factitivo del Piel: enderezar, allanar o dirigir — establecer activamente la rectitud o la nivelación de un camino, ya sea literal o metafórico. Ezequías ''dirigió'' las aguas del Guijón superior directamente hacia el lado occidental de la Ciudad de David (2 Cr 32:30); Proverbios promete ''Él enderezará tus sendas'' (Pr 3:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104953, 'spa', 'El pasivo del Pual', 'El pasivo del Pual: ser allanado, nivelado o esparcido uniformemente — la contraparte pasiva del factitivo Piel. Una sola ocurrencia en 1 Reyes 6:35 describe el recubrimiento de oro en las puertas del templo como ''ajustado'' o ''nivelado'' sobre la obra tallada. Este es el único caso pasivo, pero preserva el sentido espacial concreto de la raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104960, 'spa', 'rectitud, integridad', 'Rectitud moral e integridad de carácter. Emparejada con tom (''intachabilidad'') en el Salmo 25:21 y asociada con la disposición del corazón en Deuteronomio 9:5, 1 Reyes 9:4 y 1 Crónicas 29:17. Aplicada al discurso en Job 6:25 y Eclesiastés 12:10. Proverbios la contrasta con sendas torcidas (2:13; 4:11). Job 33:23 extiende el sentido a lo éticamente debido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104970, 'spa', 'correcto, recto (de acciones)', 'Aplicado a acciones, conducta o cosas que son correctas, rectas o agradables — 43 ocurrencias concentradas en la fórmula recurrente de la historia deuteronomista: hayyashar be''eyne YHWH, «lo recto a los ojos del SEÑOR». En Éx 15:26 Dios promete salud a Israel «si haces lo recto a sus ojos»; Dt 6:18 ordena «harás lo recto y bueno ante el SEÑOR»; y cada rey es evaluado con esta misma fórmula.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104971, 'spa', 'recto, justo (de personas)', 'Describe a una persona moralmente íntegra, justa o de buen carácter — el sentido dominante con 70 ocurrencias, término clave del vocabulario sapiencial bíblico. En Job 1:1, 1:8 y 2:3, yashar se empareja con tam («íntegro») como doble predicado de rectitud ejemplar; en Nm 23:10 Balaam desea «morir la muerte de los rectos» (yesharim). Proverbios emplea el sustantivado yesharim como cuasi-clase social de los justos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104976, 'spa', 'derecho, llano (físicamente)', 'Rectitud física, nivelación o dirección — 4 ocurrencias que describen caminos, sendas y formas corporales. En Sal 107:7 Dios condujo a los errantes por «camino derecho» (derekh yesharah) hacia una ciudad habitada; Jer 31:9 promete «los haré andar junto a arroyos de aguas, por camino derecho en que no tropezarán». Ez 1:7 describe las piernas de los seres vivientes como yesharah: «rectas», sin articulaciones visibles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (104980, 'spa', 'Yashar (Libro de Yashar)', 'Nombre propio en el título Sefer haYashar, «el Libro de Yashar» (o «del Justo») — 2 ocurrencias. En Jos 10:13 el narrador cita este libro como fuente del relato del sol detenido sobre Gabaón; en 2 S 1:18 se dice que el lamento de David por Saúl y Jonatán está escrito en él. Se trata de una colección literaria israelita perdida cuyo título mismo evoca una antología de virtud heroica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105005, 'spa', 'Israel (nombre y nación)', 'El nombre propio יִשְׂרָאֵל, otorgado primero a Jacob tras luchar con Dios en Peniel (Gn 32:28) y que desde entonces designa al pueblo de la alianza descendiente de él. Funciona en múltiples niveles —patriarca, nación de doce tribus, reino del norte y remanente escatológico—, pero constituye una sola identidad léxica. La uniformidad interlingüística es total.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105016, 'spa', 'Yisrael', 'La forma aramea del nombre nacional propio Israel (Yisra''el), usada en los contextos administrativos y proféticos de Esdras 5-7 para designar a la comunidad postexílica del pacto. Aparece en fórmulas fijas: ''Dios de Israel'' (Esd 5:1; 6:14; 7:15), ''rey de Israel'' (5:11), ''hijos de Israel'' (6:16). El español conserva ''Israel'' sin cambios, reflejando la retención universal de este nombre en todas las tradiciones lingüísticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105020, 'spa', 'Gentilicio israelita', 'Designación étnico-religiosa que señala pertenencia al pueblo del pacto. El pasaje de Levítico resalta la ascendencia mixta del blasfemo (madre israelita, padre egipcio), planteando interrogantes sobre identidad, pertenencia y estatus legal en la comunidad del desierto. La repetición de «israelita/mujer israelita» subraya esta condición liminal entre dos pueblos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105022, 'spa', 'Nombre poético de Israel', 'Jesurún aparece cuatro veces en contextos poéticos elevados: dos veces en la bendición final de Moisés («No hay como Dios, oh Jesurún», Dt 33:26; «Fue rey en Jesurún», Dt 33:5), una vez en el cántico de Moisés irónicamente antes de la apostasía de Israel («Pero Jesurún engordó y dio coces», Dt 32:15), y una vez en la promesa de Isaías («No temas, Jacob siervo mío, y Jesurún a quien yo escogí», Is 44:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105023, 'spa', 'Isacar (persona/tribu)', 'Isacar (persona/tribu)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105035, 'spa', 'Sentarse, tomar asiento', 'Sentarse o estar sentado, particularmente en un contexto de autoridad o juicio. La evidencia multilingüe converge en ''sentarse/estar sentado''. Usado en Daniel 7:9-10 y 7:26 para el juez divino que toma su trono, el cognado arameo del hebreo יָשַׁב porta todo el peso del entronamiento real y judicial en la visión apocalíptica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105036, 'spa', 'La estaca de tienda estándar — una punta de madera o metal clavada en el suelo p', 'La estaca de tienda estándar — una punta de madera o metal clavada en el suelo para anclar cuerdas y cortinas. Predomina en las descripciones del tabernáculo en Éxodo 27, 35, 38-39 y Números 3-4, donde las estacas se enumeran sistemáticamente junto con las cuerdas (metharim).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105045, 'spa', 'Una clavija usada en el tejido o montada en una pared para colgar objetos', 'Una clavija usada en el tejido o montada en una pared para colgar objetos. En Jueces 16:14 Dalila sujeta el cabello de Sansón con la clavija del telar, y en Isaías 22:23-25 una estaca fijada en lugar firme simboliza el liderazgo confiable de Eliaquim — hasta que Dios la remueve.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105047, 'spa', 'Una estaca que asegura el perímetro de una tienda, con peso metafórico de perman', 'Una estaca que asegura el perímetro de una tienda, con peso metafórico de permanencia y expansión. En Isaías 33:20 las estacas de la tienda de Sion ''nunca serán arrancadas'', y en 54:2 Dios ordena extender las cortinas y reforzar las estacas — imagen de la seguridad del pacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105054, 'spa', 'Huerfano, nino sin padre', 'Huerfano, nino sin padre. Figura paradigmatica de vulnerabilidad social en la ley del pacto. Forma parte de la triada formulaica yatom-almanah-ger (''huerfano-viuda-extranjero'') a lo largo de la literatura legal (Dt 10:18; 24:17), profetica (Is 1:17; Jer 7:6; Zac 7:10) y sapiencial (Job 29:12; 31:17). Lamentaciones 5:3 lo extiende metaforicamente al Israel del exilio. Los cognados arabe yatim y arameo yatma atestiguan una antiguedad pansemitica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105066, 'spa', 'Ciudad levítica judía', 'Jatir aparece en la asignación de ciudades montañosas de Judá (Jos 15:48), designada como ciudad levítica dada a los sacerdotes coatitas (Jos 21:14; 1Cr 6:57), y mencionada entre las ciudades a las que David envió botín tras derrotar a los amalecitas (1Sa 30:27). La Septuaginta la transcribe variadamente como Ιεθερ, Αιηλομ y Γεθθωρ, reflejando la incertidumbre griega sobre las consonantes hebreas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105067, 'spa', 'Excelente, sobresaliente', 'Uso atributivo que describe una cualidad de preeminencia, excelencia o naturaleza sobresaliente inherente a una persona o cosa. En Daniel 6:3 se halló en Daniel un ''espíritu extraordinario'' (רוּחַ יַתִּירָא), que lo distinguía de los demás funcionarios. Daniel 5:12 y 5:14 describen de modo similar una sabiduría, conocimiento y entendimiento sobresalientes como atributos personales. Daniel 4:36 marca la restauración de la majestad extraordinaria de Nabucodonosor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105068, 'spa', 'En extremo, excesivamente', 'Uso como intensificador adverbial que significa ''en extremo'', ''sobremanera'' o ''en grado sumo'', modificando un verbo u otro adjetivo en lugar de funcionar como cualidad predicada. La gran imagen del sueño de Nabucodonosor era ''en extremo'' brillante (Dan 2:31), el horno fue calentado ''excesivamente'' más de lo habitual (Dan 3:22), y la cuarta bestia era ''extraordinariamente'' aterradora y diferente de todas las demás (Dan 7:7, 19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105075, 'spa', 'lo restante, remanente (participio Nifal)', 'El participio Nifal usado como sustantivo que significa «lo restante», «el sobrante» o «el remanente» — funcionando esencialmente como nombre. Con 53 ocurrencias es el uso más frecuente, apareciendo en instrucciones rituales sobre ofrendas sobrantes (Éx 12:10; Lv 2:3), listas de tribus o territorios restantes (Éx 28:10) y resúmenes históricos de pueblos sobrevivientes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105077, 'spa', 'quedar, sobrar (Nifal finito)', 'Formas verbales Nifal finitas que expresan el sentido estativo o pasivo de permanecer, quedar o sobrevivir después de que otros han partido o han sido destruidos. Jacob «quedó solo» en Peniel (Gn 32:24), el hijo menor «queda» con su padre (Gn 44:20) y nada «quedó» después de las langostas (Éx 10:15). El español quedar/quedaron y el alemán bleiben seleccionan consistentemente verbos estativos de permanencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105085, 'spa', 'dejar como sobrante (Hifil)', 'Formas Hifil causativas que significan hacer que permanezca, dejar como excedente deliberadamente o preservar con vida — el agente elige dejar un sobrante o perdonar sobrevivientes. Las instrucciones de «no dejar nada hasta la mañana» (Éx 12:10; Lv 22:30) y promesas como «dejaré un remanente» emplean esta forma. El español dejar y dejar sobrevivir capturan la agencia causativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105086, 'spa', 'abundar, exceder (Hifil)', 'Una extensión Hifil distintiva que expresa exceso, abundancia o preeminencia — más allá del mero remanente hacia un desbordamiento de excedente. La «preeminencia en dignidad» de Rubén (Gn 49:4), los materiales que «sobraban» para el tabernáculo (Éx 36:7) y la promesa del pacto de que Dios «te hará abundar» (Dt 28:11; 30:9). El español hacer abundar y tener preeminencia reflejan este giro semántico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105142, 'spa', 'Resto, remanente, residuo — El sentido dominante', 'Resto, remanente, residuo — El sentido dominante: la porción restante o el pueblo que queda de un grupo, frecuentemente en la frase constructa «y el resto de los hechos de...» a lo largo de Reyes y Crónicas. En español se traduce «resto», en francés «reste», en alemán «Rest». Cubre los restos de cosechas dejados por las langostas (Jl 1:4), los utensilios restantes en Jerusalén (Jer 27:19) y el residuo de una asignación tribal (Dt 3:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105149, 'spa', 'Excelencia, preeminencia — Superioridad, distinción o preeminencia en cualidad', 'Excelencia, preeminencia — Superioridad, distinción o preeminencia en cualidad: un ''exceso'' de dignidad o de poder. Jacob bendice a Rubén como «preeminente en dignidad y preeminente en poder» (Gn 49:3), donde יֶתֶר no señala un sobrante sino una cualidad sobresaliente. En español se emplea «excelencia», en alemán «Vorrang» (precedencia). Proverbios 17:7 extiende esto al habla que es «excelente» o que supera lo apropiado. La idea raíz de ''más que'' subyace a este uso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105154, 'spa', 'En gran manera, más — Uso adverbial que significa ''en gran manera'' o ''más'', indi', 'En gran manera, más — Uso adverbial que significa ''en gran manera'' o ''más'', indicando un grado extraordinario. Isaías 56:12 vislumbra un mañana que será «mucho mayor» que hoy; Daniel 8:9 describe un cuerno que creció «en gran manera» en varias direcciones. En español se traduce con «mucho». Aquí el sustantivo se ha convertido en un intensificador puro, conservando el sentido de la raíz de ''más allá de la norma'' pero despojándose de su carácter nominal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105157, 'spa', 'Excedente, abundancia — Excedente, desbordamiento o abundancia más allá de lo ne', 'Excedente, abundancia — Excedente, desbordamiento o abundancia más allá de lo necesario: exceso material. El «excedente» de los impíos es consumido por el fuego (Job 22:20); Dios llena el vientre de los enemigos del salmista con «su tesoro acumulado» o «abundancia» (Sal 17:14). En español se oscila entre «abundancia» y «lo que sobró», mientras que en alemán se recurre a «Überfluss» (desbordamiento). Este sentido tiende un puente entre el remanente cuantitativo y la plenitud cualitativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105162, 'spa', 'Cuerda de arco', 'Cuerda de arco — el cordel tensado en un arco para disparar flechas. En Jueces 16:7-9, Sansón dice a Dalila que siete cuerdas de arco frescas (יְתָרִים) lo debilitarían; al atarlo ella, él las rompe ''como se rompe un hilo de estopa al fuego''. En el Salmo 11:2, los impíos ajustan su flecha ''en la cuerda'' (יֶתֶר). El cognado árabe watarun confirma este contexto de arquería.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105164, 'spa', 'Soga de tienda', 'Soga de tienda o cuerda de uso doméstico, distinta de la cuerda de arco especializada. Job 4:21 pregunta: ''¿No es arrancada su cuerda de tienda (יִתְרָם) dentro de ellos?'' — metáfora del frágil hilo de la vida. Job 30:11 emplea el término para la atadura o restricción que Dios ha soltado. El español ''su cuerda de tienda'' capta bien este sentido doméstico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105168, 'spa', 'Yéter / Jeter (nombre propio)', 'Nombre propio masculino derivado de la raíz י-ת-ר que significa ''resto, abundancia, excelencia''. Se aplica a al menos cinco individuos distintos: (a) Jeter, primogénito de Gedeón, a quien se ordenó ejecutar a Zeba y Zalmuna pero era demasiado joven para desenvainar su espada (Jue 8:20); (b) Jeter el ismaelita, padre de Amasa, a quien Absalón puso al frente del ejército (1 Re 2:5, 32; 1 Cr 2:17); (c–d) dos judítas (1 Cr 2:32; 4:17); (e) un aserita (1 Cr 7:38).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105173, 'spa', 'Jetro (nombre propio)', 'Nombre propio del suegro de Moisés, identificado como sacerdote de Madián (Éx 3:1). Las nueve ocurrencias se concentran en Éxodo 3–18, dentro de la tradición elohísta: apacentando rebaños junto al monte de Dios (3:1), enviando a Moisés a Egipto con su bendición (4:18), y el célebre reencuentro donde ofrece sacrificios y aconseja la delegación judicial (18:1–12). La variante Yéter (יֶתֶר) en Éx 4:18a se considera generalmente una forma abreviada del mismo nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105174, 'spa', 'Provecho, ventaja, ganancia', 'El sustantivo yithrôn designa provecho, ventaja o superávit: lo que queda como ganancia neta después del esfuerzo. Solo Eclesiastés lo emplea, convirtiéndolo en sello distintivo del vocabulario de Qohélet. La pregunta recurrente mah-yithrôn lā''ādām (''¿qué provecho tiene el hombre?'', Ecl 1:3; 5:16) enmarca toda la indagación existencial del libro. Puede adquirir sentido comparativo con min (''ventaja sobre'', Ecl 2:13) o constructo (''ventaja de la sabiduría'', Ecl 7:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105177, 'spa', 'Gentilicio yitrita', 'Designación gentilicia (''el yitrita'') que identifica a miembros de un clan judío procedente de Quiriat-jearim. Se aplica a dos de los guerreros de élite de David —Ira y Gareb— en 2 Sam 23:38 y 1 Cr 11:40, y aparece colectivamente entre las familias de Quiriat-jearim en 1 Cr 2:53. El artículo definido acompaña siempre a este término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (105178, 'spa', 'Nombre propio', 'Nombre personal compartido por al menos dos individuos de distintos grupos étnicos. El Yitrán edomita aparece en las genealogías horeas que Génesis preserva, mostrando el interés de los escritores bíblicos en registrar los linajes de Edom, nación hermana de Israel descendiente de Esaú. Su uso entre los aseritas indica que el nombre también circulaba entre las tribus israelitas.');